import fs from "node:fs/promises";
import { createReadStream } from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { ensure } from "./files.ts";

export const LOG_PREVIEW_BYTES = 64 * 1024;
export const DEFAULT_LOG_BYTES = 256 * 1024 * 1024;
export interface LogBudget {
  maxBytes: number;
  usedBytes: number;
  error?: string;
}
export interface ProcessLogOptions {
  stdoutPath: string;
  stderrPath: string;
  budget: LogBudget;
  secrets?: string[];
}
export interface LoggedStream {
  path: string;
  bytes: number;
  sha256?: string;
  preview_truncated: boolean;
}
export interface ProcessLogs {
  stdout: LoggedStream;
  stderr: LoggedStream;
  complete: boolean;
  error?: string;
}
export async function fileHash(file: string) {
  const hash = crypto.createHash("sha256");
  for await (const part of createReadStream(file)) hash.update(part);
  return "sha256:" + hash.digest("hex");
}

// Keep enough undecided text to recognize a secret split across pipe chunks.
class Redactor {
  private pending = "";
  private secrets: string[];
  private keep: number;
  constructor(secrets: string[]) {
    this.secrets = [...new Set(secrets.filter(Boolean))].sort(
      (a, b) => b.length - a.length,
    );
    this.keep = Math.max(0, ...this.secrets.map((s) => s.length - 1));
  }
  push(text: string, final = false) {
    if (!this.secrets.length) return text;
    this.pending += text;
    const limit = final
      ? this.pending.length
      : Math.max(0, this.pending.length - this.keep);
    let pos = 0,
      output = "";
    while (pos < limit) {
      let first = -1,
        match = "";
      for (const secret of this.secrets) {
        const found = this.pending.indexOf(secret, pos);
        if (found >= 0 && (first < 0 || found < first)) {
          first = found;
          match = secret;
        }
      }
      if (first < 0 || first >= limit) {
        output += this.pending.slice(pos, limit);
        pos = limit;
      } else {
        output += this.pending.slice(pos, first) + "[REDACTED]";
        pos = first + match.length;
      }
    }
    // Never separate a UTF-16 surrogate pair when holding the redaction suffix.
    if (
      pos > 0 &&
      pos < this.pending.length &&
      /[\uD800-\uDBFF]/.test(this.pending[pos - 1])
    ) {
      output = output.slice(0, -1);
      pos--;
    }
    this.pending = this.pending.slice(pos);
    return output;
  }
}

function utf8Prefix(data: Buffer, maximum: number) {
  let end = Math.min(maximum, data.length);
  if (end < data.length) while (end > 0 && (data[end] & 0xc0) === 0x80) end--;
  return data.subarray(0, end);
}
function utf8Tail(data: Buffer, maximum: number) {
  let start = Math.max(0, data.length - maximum);
  while (start < data.length && (data[start] & 0xc0) === 0x80) start++;
  return data.subarray(start);
}

export class LogSink {
  private handle?: fs.FileHandle;
  private redactor: Redactor;
  private head: Buffer = Buffer.alloc(0);
  private tail: Buffer = Buffer.alloc(0);
  private seen = 0;
  private failed = false;
  readonly file: string;
  private budget: LogBudget;
  private stop: () => void;
  constructor(
    file: string,
    budget: LogBudget,
    secrets: string[],
    stop: () => void,
  ) {
    this.file = file;
    this.budget = budget;
    this.stop = stop;
    this.redactor = new Redactor(secrets);
  }
  fail(code = "LOG_WRITE_FAILED") {
    this.failed = true;
    this.budget.error ??= code;
    this.stop();
  }
  async open() {
    try {
      await fs.mkdir(path.dirname(this.file), { recursive: true });
      this.handle = await fs.open(this.file, "wx");
    } catch {
      this.fail();
    }
  }
  async append(text: string, final = false) {
    if (this.failed || this.budget.error) return;
    const safe = this.redactor.push(text, final);
    if (!safe) return;
    const data = Buffer.from(safe, "utf8");
    const remaining = Math.max(0, this.budget.maxBytes - this.budget.usedBytes);
    const bytes = utf8Prefix(data, remaining);
    // Reserve shared quota before awaiting I/O from either output stream.
    this.budget.usedBytes += bytes.length;
    try {
      if (!this.handle) throw new Error("Log not open");
      if (bytes.length) await this.handle.writeFile(bytes);
      this.seen += bytes.length;
      if (this.head.length < LOG_PREVIEW_BYTES)
        this.head = utf8Prefix(
          Buffer.concat([this.head, bytes]),
          LOG_PREVIEW_BYTES,
        );
      this.tail = utf8Tail(
        Buffer.concat([this.tail, bytes]),
        LOG_PREVIEW_BYTES / 2,
      );
    } catch {
      this.fail();
    }
    if (bytes.length !== data.length) this.fail("LOG_LIMIT_EXCEEDED");
  }
  preview() {
    if (this.seen <= LOG_PREVIEW_BYTES) return this.head.toString("utf8");
    const marker = "\n[PREVIEW_TRUNCATED: 完整内容见日志文件]\n";
    const head = utf8Prefix(
      this.head,
      LOG_PREVIEW_BYTES / 2 - Buffer.byteLength(marker),
    );
    return head.toString("utf8") + marker + this.tail.toString("utf8");
  }
  async close(): Promise<LoggedStream> {
    try {
      await this.handle?.sync();
    } catch {
      this.fail();
    }
    try {
      await this.handle?.close();
    } catch {
      this.fail();
    }
    const meta: LoggedStream = {
      path: this.file,
      bytes: 0,
      preview_truncated: this.seen > LOG_PREVIEW_BYTES,
    };
    // Do not read an unrelated pre-existing file if exclusive creation failed.
    if (this.handle) {
      try {
        meta.bytes = (await fs.stat(this.file)).size;
        meta.sha256 = await fileHash(this.file);
      } catch {
        this.fail();
      }
    }
    return meta;
  }
}

export async function readLogPage(file: string, offset: number) {
  ensure(
    Number.isSafeInteger(offset) && offset >= 0,
    "OFFSET",
    "字节偏移必须为非负安全整数",
  );
  const h = await fs.open(file, "r");
  try {
    const size = (await h.stat()).size;
    const bytes = Buffer.alloc(LOG_PREVIEW_BYTES + 4);
    const { bytesRead } = await h.read(bytes, 0, bytes.length, offset);
    const data = bytes.subarray(0, bytesRead);
    ensure(
      !data.length || (data[0] & 0xc0) !== 0x80,
      "OFFSET",
      "偏移位于 UTF-8 字符内部，请使用 next_byte_offset",
    );
    const page = utf8Prefix(data, LOG_PREVIEW_BYTES);
    const next = offset + page.length;
    return {
      text: page.toString("utf8"),
      byte_offset: offset,
      total_bytes: size,
      truncated: next < size,
      next_byte_offset: next < size ? next : null,
    };
  } finally {
    await h.close();
  }
}

// Legacy inspect offsets count UTF-16 characters. Scan without retaining the full log.
export async function readCharacterPage(
  file: string,
  offset: number,
  limit = 50000,
) {
  let total = 0,
    text = "";
  for await (const part of createReadStream(file, { encoding: "utf8" })) {
    const chunk = String(part),
      start = Math.max(0, offset - total);
    const end = Math.min(chunk.length, offset + limit - total);
    if (end > start) text += chunk.slice(start, end);
    total += chunk.length;
  }
  return {
    text,
    offset,
    total_chars: total,
    truncated: offset + limit < total,
    next_offset: offset + limit < total ? offset + limit : null,
  };
}
